1	// Package indexroom implements chain ingestion with reorg handling.
2	package indexroom
3	
4	import (
5		"encoding/json"
6		"fmt"
7		"net"
8		"sort"
9		"strconv"
10		"strings"
11	)
12	
13	// InstanceInput is one submitted service instance, decoded from JSON.
14	type InstanceInput struct {
15		ID      json.RawMessage `json:"id"`
16		Address json.RawMessage `json:"address"`
17	}
18	
19	// RegisterRequest is one registration entry decoded from JSON.
20	type RegisterRequest struct {
21		Service         json.RawMessage `json:"service"`
22		ExpectedRevision json.RawMessage `json:"expectedRevision"`
23		Instances       json.RawMessage `json:"instances"`
24	}
25	
26	// Instance is a validated service instance stored in the registry.
27	type Instance struct {
28		ID      string `json:"id"`
29		Address string `json:"address"`
30	}
31	
32	// ServiceRecord is the current state of one registered service.
33	type ServiceRecord struct {
34		Service  string     `json:"service"`
35		Revision int        `json:"revision"`
36		Instances []Instance `json:"instances"`
37	}
38	
39	type validationError struct{ msg string }
40	
41	func (e *validationError) Error() string { return e.msg }
42	
43	type conflictError struct{ expected, actual int }
44	
45	func (e *conflictError) Error() string {
46		return fmt.Sprintf("expected revision %d but service is at revision %d", e.expected, e.actual)
47	}
48	
49	// Registry keeps service instance lists for one offline registration run.
50	// Each run starts from an empty registry.
51	type Registry struct {
52		services map[string]*ServiceRecord
53	}
54	
55	// NewRegistry returns an empty registry.
56	func NewRegistry() *Registry {
57		return &Registry{services: map[string]*ServiceRecord{}}
58	}
59	
60	// RegisterResult is the per-request outcome, encoded with type-specific fields.
61	type RegisterResult struct {
62		Kind     string // "success" | "invalid" | "conflict"
63		Service  string
64		Revision int    // revision that remains in effect after the attempt (0 when the service is absent)
65		Changed  bool   // success only: whether the stored list changed
66		Reason   string // failure only
67		Expected int    // conflict only: revision the request asked for
68		Actual   int    // conflict only: revision the service currently has
69	}
70	
71	// MarshalJSON renders a discriminated result without fields that do not apply.
72	func (r RegisterResult) MarshalJSON() ([]byte, error) {
73		if r.Kind == "success" {
74			return json.Marshal(struct {
75				Status   string `json:"status"`
76				Service  string `json:"service"`
77				Revision int    `json:"revision"`
78				Changed  bool   `json:"changed"`
79			}{r.Kind, r.Service, r.Revision, r.Changed})
80		}
81		out := struct {
82			Status        string `json:"status"`
83			Service       string `json:"service"`
84			Reason        string `json:"reason"`
85			ActualRevision int    `json:"actualRevision"`
86			Expected      *int   `json:"expectedRevision,omitempty"`
87			Actual        *int   `json:"currentRevision,omitempty"`
88		}{Status: r.Kind, Service: r.Service, Reason: r.Reason, ActualRevision: r.Revision}
89		if r.Kind == "conflict" {
90			out.Expected = &r.Expected
91			out.Actual = &r.Actual
92		}
93		return json.Marshal(out)
94	}
95	
96	// Apply validates one request and, when the revision matches, replaces the
97	// service's whole instance list. Invalid input is rejected before the
98	// revision is examined, so a failed request never creates a service, leaves
99	// partial instances, or consumes a revision.
100	func (reg *Registry) Apply(req RegisterRequest) RegisterResult {
101		service, expected, instances, err := validateRequest(req)
102		result := RegisterResult{Service: service}
103		if err != nil {
