		results := mustBatch(t, reg, input)
		if results[0].Kind != "invalid" {
			t.Errorf("expectedRevision %s accepted: %+v", value, results[0])
		}
	}
	reg := NewRegistry()
	results := mustBatch(t, reg, `{"requests":[{"service":"s","instances":[]}]}`)
	if results[0].Kind != "invalid" {
